-- PT119-S3-Q20. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT119-S3-Q20$batch06$ AND q.stimulus=$batch06$Scientist: Genetic engineering has aided new developments in many different fields. But because these techniques require the manipulation of the genetic codes of organisms, they are said to be unethical. What the critics fail to realize is that this kind of manipulation has been going on for millennia; virtually every farm animal is the result of selective breeding for desired traits. Since selective breeding is genetic engineering of a crude sort, genetic engineering is not unethical.$batch06$ AND q.prompt=$batch06$Which one of the following is an assumption on which the scientist's argument depends?$batch06$ AND q.correct_choice=$batch06$C$batch06$) THEN RAISE EXCEPTION 'Question changed: PT119-S3-Q20'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch06$3dbbe7ec-5548-455f-b9e4-fa006c62eaf5$batch06$) <> 4 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch06$3dbbe7ec-5548-455f-b9e4-fa006c62eaf5$batch06$) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT119-S3-Q20'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$"Never unethical" covers every possible case. The scientist only needs selective breeding, and genetic engineering like it, to be acceptable.$batch06$), ($batch06$B$batch06$, $batch06$This is the most popular wrong answer, and it is easy to see why: it sounds like a defense of genetic engineering. But the scientist's argument is about a long human *practice* (selective breeding), not about what nature does. Negate B and the argument still stands.$batch06$), ($batch06$C$batch06$, $batch06$Negate it: "selective breeding for desired traits *is* unethical." Then pointing out that we have done it for millennia only shows we have been doing something wrong for a long time. It no longer clears genetic engineering, and the conclusion falls.$batch06$), ($batch06$D$batch06$, $batch06$Whether selective breeding is important for survival says nothing about whether it is ethical.$batch06$), ($batch06$E$batch06$, $batch06$A sweeping claim about science and nature that the argument never uses.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT119-S3-Q20$batch06$ AND e.id=$batch06$3dbbe7ec-5548-455f-b9e4-fa006c62eaf5$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
